  "Illiberális fordulat": "<svg class=\"card-art-svg type-Korszak fac-KOR\" viewBox=\"0 0 200 150\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"200\" height=\"150\" fill=\"#FDF6E2\"/>\n  <!-- Parchment border & roman numeral seal -->\n  <rect x=\"10\" y=\"10\" width=\"180\" height=\"130\" rx=\"4\" fill=\"none\" stroke=\"#9A7842\" stroke-width=\"2\" stroke-dasharray=\"6 3\"/>\n  <!-- Giant Year in background -->\n  <text x=\"100\" y=\"55\" font-family=\"sans-serif\" font-size=\"34\" fill=\"#9A7842\" opacity=\"0.35\" font-weight=\"900\" text-anchor=\"middle\">2014</text>\n  <!-- Roman Numeral Badge -->\n  <rect x=\"20\" y=\"16\" width=\"30\" height=\"14\" rx=\"2\" fill=\"#9A7842\"/>\n  <text x=\"26\" y=\"27\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"bold\">I.</text>\n  \n  <g transform=\"translate(100, 75)\">\n    <!-- Tusnádfürdő pine trees and sun -->\n    <polygon points=\"-30,15 -15,-15 0,15\" fill=\"#1E8449\"/>\n    <polygon points=\"0,15 15,-15 30,15\" fill=\"#145A32\"/>\n    <circle cx=\"0\" cy=\"-18\" r=\"10\" fill=\"#F39C12\"/>\n  </g>\n\n  <!-- Title banner -->\n  <rect x=\"25\" y=\"115\" width=\"150\" height=\"18\" rx=\"2\" fill=\"#7A5E33\"/>\n  <text x=\"100\" y=\"128\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"900\" text-anchor=\"middle\">ILLIBERÁLIS FORDULAT</text></svg>",
  "Kerítés a déli határon": "<svg class=\"card-art-svg type-Korszak fac-KOR\" viewBox=\"0 0 200 150\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"200\" height=\"150\" fill=\"#FDF6E2\"/>\n  <!-- Parchment border & roman numeral seal -->\n  <rect x=\"10\" y=\"10\" width=\"180\" height=\"130\" rx=\"4\" fill=\"none\" stroke=\"#9A7842\" stroke-width=\"2\" stroke-dasharray=\"6 3\"/>\n  <!-- Giant Year in background -->\n  <text x=\"100\" y=\"55\" font-family=\"sans-serif\" font-size=\"34\" fill=\"#9A7842\" opacity=\"0.35\" font-weight=\"900\" text-anchor=\"middle\">2015</text>\n  <!-- Roman Numeral Badge -->\n  <rect x=\"20\" y=\"16\" width=\"30\" height=\"14\" rx=\"2\" fill=\"#9A7842\"/>\n  <text x=\"26\" y=\"27\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"bold\">II.</text>\n  \n  <g transform=\"translate(100, 75)\">\n    <line x1=\"-50\" y1=\"0\" x2=\"50\" y2=\"0\" stroke=\"#7F8C8D\" stroke-width=\"4\"/>\n    <path d=\"M-40 0 Q-30 -15 -20 0 T0 0 T20 0 T40 0\" stroke=\"#BDC3C7\" stroke-width=\"3\" fill=\"none\"/>\n  </g>\n\n  <!-- Title banner -->\n  <rect x=\"25\" y=\"115\" width=\"150\" height=\"18\" rx=\"2\" fill=\"#7A5E33\"/>\n  <text x=\"100\" y=\"128\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"900\" text-anchor=\"middle\">KERÍTÉS A DÉLI HATÁRON</text></svg>",
