  "Kvótanépszavazás": "<svg class=\"card-art-svg type-Korszak fac-KOR\" viewBox=\"0 0 200 150\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"200\" height=\"150\" fill=\"#FDF6E2\"/>\n  <!-- Parchment border & roman numeral seal -->\n  <rect x=\"10\" y=\"10\" width=\"180\" height=\"130\" rx=\"4\" fill=\"none\" stroke=\"#9A7842\" stroke-width=\"2\" stroke-dasharray=\"6 3\"/>\n  <!-- Giant Year in background -->\n  <text x=\"100\" y=\"55\" font-family=\"sans-serif\" font-size=\"34\" fill=\"#9A7842\" opacity=\"0.35\" font-weight=\"900\" text-anchor=\"middle\">2016</text>\n  <!-- Roman Numeral Badge -->\n  <rect x=\"20\" y=\"16\" width=\"30\" height=\"14\" rx=\"2\" fill=\"#9A7842\"/>\n  <text x=\"26\" y=\"27\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"bold\">II.</text>\n  \n  <g transform=\"translate(100, 75)\">\n    <circle cx=\"0\" cy=\"0\" r=\"22\" fill=\"#C0392B\" stroke=\"#1B1A18\" stroke-width=\"2\"/>\n    <text x=\"-12\" y=\"8\" font-family=\"sans-serif\" font-size=\"16\" fill=\"#FFF\" font-weight=\"900\">NEM</text>\n  </g>\n\n  <!-- Title banner -->\n  <rect x=\"25\" y=\"115\" width=\"150\" height=\"18\" rx=\"2\" fill=\"#7A5E33\"/>\n  <text x=\"100\" y=\"128\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"900\" text-anchor=\"middle\">KVÓTANÉPSZAVAZÁS</text></svg>",
