  "Önkormányzati fordulat": "<svg class=\"card-art-svg type-Korszak fac-KOR\" viewBox=\"0 0 200 150\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"200\" height=\"150\" fill=\"#FDF6E2\"/>\n  <!-- Parchment border & roman numeral seal -->\n  <rect x=\"10\" y=\"10\" width=\"180\" height=\"130\" rx=\"4\" fill=\"none\" stroke=\"#9A7842\" stroke-width=\"2\" stroke-dasharray=\"6 3\"/>\n  <!-- Giant Year in background -->\n  <text x=\"100\" y=\"55\" font-family=\"sans-serif\" font-size=\"34\" fill=\"#9A7842\" opacity=\"0.35\" font-weight=\"900\" text-anchor=\"middle\">2019</text>\n  <!-- Roman Numeral Badge -->\n  <rect x=\"20\" y=\"16\" width=\"30\" height=\"14\" rx=\"2\" fill=\"#9A7842\"/>\n  <text x=\"26\" y=\"27\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"bold\">III.</text>\n  \n  <g transform=\"translate(100, 75)\">\n    <!-- Budapest Chain bridge silhouette -->\n    <path d=\"M-40 10 L-25 -15 L-20 10 L20 10 L25 -15 L40 10\" stroke=\"#2ECC71\" stroke-width=\"3\" fill=\"none\"/>\n    <circle cx=\"0\" cy=\"-5\" r=\"8\" fill=\"#F1C40F\"/>\n  </g>\n\n  <!-- Title banner -->\n  <rect x=\"25\" y=\"115\" width=\"150\" height=\"18\" rx=\"2\" fill=\"#7A5E33\"/>\n  <text x=\"100\" y=\"128\" font-family=\"sans-serif\" font-size=\"8\" fill=\"#FFF\" font-weight=\"900\" text-anchor=\"middle\">ÖNKORMÁNYZATI FORDULAT</text></svg>",
